import {createContextualEvidencePanel} from './contextual-evidence.js';
import {formatMoneyMillions,formatTimestamp,compactAnnualPeriod,parseDisplayedNumber,comparisonText} from './display-format.js';
import {RESEARCH_PATH,RESEARCH_VERSION,RESEARCH_STORAGE_PREFIX,researchDraftFor,restoreResearchDraft,loadAnnualResearchCase,calculateResearchOperating,terminalNormalizedDraft,researchTimingResult,researchSensitivity,exportResearchCase} from './research-model.js';
