const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const finite=x=>typeof x==='number'&&Number.isFinite(x);
const num=(n,d=1)=>finite(n)?n.toLocaleString('en-US',{maximumFractionDigits:d}):'Not computed';
const pct=n=>finite(n)?`${num(n*100,2)}%`:'Not meaningful';
const amount=(n,c)=>esc(formatMoneyMillions(n,c));
const plain=n=>finite(n)?String(n):'';
const readableKey=key=>String(key??'Unknown').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/_/g,' ').replace(/^./,x=>x.toUpperCase());
function capitalScenarioEdited(d){
 if(!Object.prototype.hasOwnProperty.call(d||{},'currentCapitalScenario'))return false;
 const preset=getCurrentCapitalPreset(d.ticker);
 return !preset||JSON.stringify(d.currentCapitalScenario)!==JSON.stringify(preset.scenario)||JSON.stringify(d.timing)!==JSON.stringify(preset.timing);
}
const annualScenarioLabel=d=>d?.derivedForecast?'Derived analyst scenario':d?.userEdited?'Your annual scenario':capitalScenarioEdited(d)?'Your capital scenario':'Reviewed annual case';
function rationaleHTML(value){
 if(value===null||value===undefined)return '';
 if(Array.isArray(value))return `<ul>${value.map(item=>`<li>${rationaleHTML(item)}</li>`).join('')}</ul>`;
 if(typeof value==='object')return `<dl class="preset-reasoning">${Object.entries(value).filter(([key])=>key!=='sourceUrls').map(([key,item])=>`<dt>${esc(readableKey(key))}</dt><dd>${rationaleHTML(item)}</dd>`).join('')}</dl>`;
 return esc(value);
}
export function researchPresetHTML(d,bundle,{error=null,ticker=d?.ticker,undoAvailable=false}={}){
 const available=studioPresetFor(bundle,ticker),p=d?.researchPreset;
 if(error)return `<div class="research-warning"><b>Complete preset unavailable</b><p>${esc(error)} Existing annual inputs are retained; the complete preset cannot be applied.</p></div>`;
 if(!available)return '';
 const rationale=p?.rationale||available.rationale,config=d?.researchSimulationConfig;
 const current=p?researchPresetStatus(d,bundle):'Saved annual inputs retained · complete research preset available';
 const simulations=config?.drivers?table('Selected Monte Carlo assumptions; percentage-point shifts, investment as a multiple',['Driver','Family','Hyperparameters'],Object.entries(config.drivers).map(([key,rawSpec])=>{const spec=rawSpec&&typeof rawSpec==='object'?rawSpec:{};return [esc(readableKey(key)),esc(spec.type==='normal'?'Truncated normal':readableKey(spec.type)),Object.entries(spec).filter(([name])=>name!=='type').map(([name,value])=>`${esc(readableKey(name))} ${esc(finite(value)?num(value*(key==='investmentMultiplier'?1:100),4):value)}${key==='investmentMultiplier'?'×':' pp'}`).join(' · ')]})):'';
 const sources=rationale?.sourceUrls||[],methodSources=p?.methodologySources||bundle.methodology?.damodaranSources||[];
 return `<section class="research-preset-context" aria-label="Complete research preset"><div class="preset-heading"><div><span class="eyebrow">RESEARCH · ${esc(bundle.asOf)}</span><p id="research-preset-state">${esc(current)}</p></div></div><p>Loads all annual, terminal, dated-claims and Monte Carlo inputs together. Full Undo preserves your prior case; notes stay.</p><details class="preset-rationale"><summary>Why this complete case? · growth, capital and uncertainty</summary><p class="micro">Preset ${esc(p?.version||bundle.version)} · research as of ${esc(p?.asOf||bundle.asOf)}. ${p?'Selected preset provenance; your edits remain visible in the controls below.':'The research preset has not replaced this saved draft.'}</p><p>${esc(rationale?.headline||'Company-specific annual economics and conditional uncertainty.')}</p><p><b>Revenue-growth duration:</b> ${esc(rationale?.revenueGrowthHorizonYears??d?.forecastHorizonYears)} years. Margin and investment retain their separate researched annual paths; a longer growth horizon does not postpone profitability or capital efficiency automatically.</p>${rationaleHTML(rationale)}<h3>Model parameter reasoning</h3>${rationaleHTML(p?.parameterRationale||available.parameterRationale)}<h3>Monte Carlo settings and reasoning</h3>${simulations}${config?`<p>${esc(config.trials)} attempted trials · seed ${esc(config.seed)} · ${esc(config.binCount)} bins · dependence ${esc(config.dependence)} · capital policy ${esc(config.capitalPolicy)}.</p>`:''}${rationaleHTML(p?.simulationRationale||available.simulationRationale)}<p>These distributions are explicit analyst judgments. Their frequencies are conditional model outcomes, not calibrated probabilities. Independent draws are a simplifying assumption; the capital-response policy is a separate relationship.</p>${sources.length?`<ul>${sources.map(url=>`<li>${link(url,'Original research source')}</li>`).join('')}</ul>`:''}${methodSources.length?`<h3>Primary methodology examples</h3><ul>${methodSources.map(source=>`<li>${link(source.url,source.title)}${source.use?` · ${esc(source.use)}`:''}</li>`).join('')}</ul>`:''}<p>${link(`./data/studio-research-presets-2026-10-17-v1.html#${ticker}`,'Readable company preset report')} · ${link(STUDIO_PRESETS_PATH,'Complete preset and named alternatives (JSON)')}</p></details></section>`;
}
const link=(path,text)=>`<a href="${esc(path)}" target="_blank" rel="noopener">${esc(text)} ↗</a>`;
const table=(caption,headers,rows)=>`<div class="research-table-scroll" tabindex="0" role="region" aria-label="${esc(caption)}"><table class="research-table"><caption>${esc(caption)}</caption><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,i)=>i===0?`<th scope="row">${cell}</th>`:`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const list=xs=>`<ul>${(xs||[]).map(x=>`<li>${esc(typeof x==='string'?x:x.message||x.description||JSON.stringify(x))}</li>`).join('')}</ul>`;
const input=(key,value,label,{scale=1,step='any',min,max,group='annual',index}={})=>{
 const raw=finite(value)?value*scale:null,annual=group==='annual',capital=group==='current-capital',formatted=annual||capital;
 const digits=capital?(/(?:Shares|shares|sharesAdded)$/.test(key)?6:2):scale===100?2:1,shown=formatted&&finite(raw)?num(raw,digits):plain(raw);
 return `<input type="${formatted?'text':'number'}" inputmode="decimal" data-research-input="${group}" data-field="${esc(key)}" data-scale="${scale}" ${index===undefined?'':`data-index="${index}"`} ${formatted?`data-raw="${plain(raw)}" data-display-digits="${digits}" ${annual?'aria-describedby="annual-edit-help"':''} title="Exact value: ${plain(raw)}"`:''} value="${shown}" step="${step}" ${min===undefined?'':`min="${min}"`} ${max===undefined?'':`max="${max}"`} aria-label="${esc(label)}">`;
};

function startingComparison(c,d,startingDraft,current,kind='operating'){
 if(!startingDraft)return '';
 try{
  const baseOperating=calculateResearchOperating(startingDraft),baseTiming=researchTimingResult(startingDraft,baseOperating),nowTiming=researchTimingResult(d,calculateResearchOperating(d));
  if(baseTiming.status!==nowTiming.status||baseTiming.date!==nowTiming.date)return '<p class="value-change comparison-unavailable">Starting-case comparison is unavailable across different valuation dates or timing states.</p>';
  let starting=baseTiming.status==='incomplete'?baseOperating.enterprise:baseTiming.enterprise;
  if(kind==='share')starting=calculateResearchBridge(startingDraft,baseTiming.enterprise,{...(startingDraft.bridgeInputs||{}),calculationDate:baseTiming.date}).rawPerShare;
  if(!finite(starting)||!finite(current))return '';
  const text=comparisonText(current,starting,{money:kind==='operating',currency:d.currency,unit:kind==='share'?` ${d.currency} / ${d.currency==='TWD'?'ordinary share':'share'}`:'',label:'from starting case'});
  return `<p class="value-change" data-value-change="${kind}">${esc(text)}</p>`;
 }catch{return '';}
}

function bridgeSensitivityHTML(d,timing){
 if(!finite(timing.enterprise))return '';
 try{const rows=researchBridgeSensitivity(d,timing.enterprise,{...(d.bridgeInputs||{}),calculationDate:timing.date});if(!rows.length)return '';return `<details><summary>Named capital-allocation sensitivities</summary>${table('Common allocation per share; conditional source-date scenarios',['Scenario',`${d.currency} / share`],rows.map(r=>[esc(r.label),finite(r.rawPerShare)?num(r.rawPerShare,2):'Not computed']))}<p class="micro">These cases are distinct treatments, not a probability range. Principal-only convertible stress omits option value. Unpriced claims are still disclosed in every case.</p></details>`;}catch{return '';}
}
function capitalDiagnosticHTML(bridge,currency){
 if(!finite(bridge?.preclaimResidual))return '';
 return `<p class="research-warning capital-preclaim-diagnostic"><b>${bridge.preclaimResidual<0?'No positive common residual in this operating scenario, even before debt.':'Before-debt residual only; common-equity claims remain unresolved.'}</b> Operating value plus the selected cash and nonoperating assets, before unresolved claims: ${amount(bridge.preclaimResidual,currency)}${finite(bridge.preclaimPerShare)?` · ${num(bridge.preclaimPerShare,2)} ${esc(currency)} per reference share`:''}. This is a funding diagnostic, not a stock fair value. Different operating or capital-spending assumptions can change it.</p>`;
}
function capitalEvidenceHTML(c,d){
 const rows=c.annual.flatMap(r=>Object.entries(r.capitalComponents||{}).filter(([,v])=>finite(v)).map(([key,value])=>[String(r.year),esc(key.replace(/_/g,' ')),num(value,2)]));
 return `<details class="research-card"><summary>Original gross-to-net investment evidence</summary><p>Authoritative annual net investment is deducted once. ${d.userEdited?'Your edited path may no longer reconcile to these original components.':'These components belong to the preserved reviewed case.'}</p>${rows.length?table('Original capital components, company currency millions',['Year','Component','Amount'],rows):'<p>No complete annual gross-capex, D&A, lease and working-capital decomposition is supplied for this selected case. Its net-investment schedule is an analytical proxy, not proof of a maintenance budget.</p>'}<p class="micro">Missing later components are unmodeled, not zero spending. Customer advances and finance-lease effects enter once under the linked company policy. SBC is already an economic cost in EBIT; its cash-funding addback does not raise economic FCFF.</p>${link(`./data/renewed-research-2026-10-17/evidence-${c.ticker}.html#selected-case`,'Investment provenance and bounded gaps')}</details>`;
}

export function researchResultsHTML(c,d,{identityError=null,region='all',startingDraft=null}={}){
 if(identityError)return region==='analysis'?'':`<div class="error"><h2>Saved draft needs attention</h2><p>${esc(identityError)}</p><p>Your saved draft has been retained. Export it, or explicitly load the reviewed case. Undo restores the full previous draft.</p></div>`;
 try{
  const r=calculateResearchOperating(d),timing=researchTimingResult(d,r),s=researchSensitivity(d);
  let bridge=null;try{if(timing.status!=='incomplete')bridge=calculateResearchBridge(d,timing.enterprise,{...(d.bridgeInputs||{}),calculationDate:timing.date});}catch(e){bridge={message:e.message,warnings:['The operating calculation remains valid; the equity bridge needs correction.']};}
  const equity=bridge?.equity,perShare=bridge?.rawPerShare;
  const bridgeReady=finite(equity)&&finite(perShare);
  const terminalWarning=r.warnings.length?`<div class="research-warning"><b>Model transitions to inspect</b>${list(r.warnings)}</div>`:'';
  const markup=`<section class="research-value" aria-label="Conditional researched operating value"><span class="eyebrow">${d.derivedForecast?'DERIVED ANALYST SCENARIO':d.userEdited?'EDITED ANNUAL SCENARIO':capitalScenarioEdited(d)?'EDITED CAPITAL SCENARIO':'REVIEWED ANNUAL RESEARCH'} · ${esc(d.currency)} MILLIONS IN TABLES</span><h2>${timing.status==='scenario'?'As-of operating scenario':'Forecast-origin operating value'}</h2><p class="research-big-value">${amount(timing.status==='incomplete'?r.enterprise:timing.enterprise,d.currency)}</p>${startingComparison(c,d,startingDraft,timing.status==='incomplete'?r.enterprise:timing.enterprise)}<details class="exact-value"><summary>Exact operating value</summary><p>${esc(plain(timing.status==='incomplete'?r.enterprise:timing.enterprise))} ${esc(d.currency)} millions. Display rounding never changes the model.</p><p class="comparison-basis">Starting case = this company’s opening draft this session. The difference includes all your changes, not investment return.</p><p>Peak economic deficit is cumulative operating cash use before financing, reserves, coupons and other uses. It is never deducted again as debt.</p></details><p class="research-date-line">${timing.status==='scenario'?`Scenario date <time datetime="${esc(timing.date)}">${esc(formatTimestamp(timing.date))}</time>`:`Discount origin <time datetime="${esc(d.discountOrigin)}">${esc(formatTimestamp(d.discountOrigin))}</time>`} · information through <time datetime="${esc(d.informationAsOf)}">${esc(formatTimestamp(d.informationAsOf))}</time></p><p>${timing.status==='incomplete'?'Origin value remains visible while the as-of bridge is incomplete.':timing.status==='scenario'?'Explicit timing assumptions; the cash-flow stub is not an observed actual.':c.anchor.kind==='management_full_year_forecast'?'Management full-year forecast anchor, not reported actuals. An October value needs the remaining pre-origin cash-flow stub.':'Uses later research information; this was not a value knowable on the anchor date.'}</p>${timing.status==='incomplete'?`<div class="research-warning"><b>As-of value not computed</b><p>${esc(timing.message)}</p></div>`:''}<div class="research-stat-grid"><div><span>Full calculation</span><b>${r.rows.length} years</b></div><div><span>Terminal PV / origin EV</span><b>${pct(r.terminalShare)}</b></div><div><span>Peak economic deficit</span><b>${amount(r.peakEconomicDeficit,d.currency)}</b></div></div><p class="micro">${r.negativeFCFFYears} negative-FCFF years. See exact-value details for the deficit definition.</p>${r.enterprise<0?'<div class="research-warning"><b>Negative operating value is preserved.</b><p>This conditional business path consumes more capital than its discounted earnings support. It is not a traded-security price or a prediction of default.</p></div>':''}</section>
  <section class="research-card research-equity"><h2>From operations to common equity</h2>${capitalDiagnosticHTML(bridge,d.currency)}${bridgeReady?`<p class="research-equity-value">${num(perShare,2)} ${esc(d.currency)} <small>/ ${d.currency==='TWD'?'ordinary share':'common share'}</small></p>${startingComparison(c,d,startingDraft,perShare,'share')}<p><b>${esc(bridge.allocationLabel||'Conditional source-date common allocation')}</b></p>${equity<0?`<p class="research-warning">Signed common equity ${amount(equity,d.currency)}; limited-liability display floor ${num(bridge.flooredPerShare??0,2)} per share.</p>`:''}`:`<p class="research-warning">${esc(bridge?.message||bridge?.reason||bridge?.reasons?.join(' ')||'Common-equity output is incomplete. The operating scenario above remains available.')}</p>`}${bridge?`<p class="micro">${(bridge.capitalReferenceDate||bridge.referenceDate)===bridge.shareReferenceDate?`Capital and shares: ${esc(formatTimestamp(bridge.shareReferenceDate||'see line items'))}`:`Capital: ${esc(formatTimestamp(bridge.capitalReferenceDate||bridge.referenceDate||'see line items'))} · shares: ${esc(formatTimestamp(bridge.shareReferenceDate||'see share basis'))}`}</p>${bridge.warnings?.length?list(bridge.warnings.slice(0,2)):''}`:''}${c.ticker==='LITE'?`<p class="micro">${link('./data/renewed-reviews-2026-10-17/LITE-dated-bridge-v2.html','June bridge review and conversion-request correction')}. Employee claims remain incomplete; this is not a current October price.</p>`:''}${c.ticker==='AAOI'&&!d.currentCapitalScenario?'<p>The earlier June TTM Guided model has its reviewed convertible/warrant bridge. This December forecast-origin case needs a separate 2026 capital roll-forward.</p><button class="quiet" data-research-action="legacy">Open prior AAOI source-date model</button>':''}<details class="research-allocation-details"><summary>Equity allocation details and claims</summary>${bridgeReady?`<p>Signed common equity ${amount(equity,d.currency)}. Per-share changes compare with this company’s opening draft this session; they are model changes, not investment returns.</p>`:''}${bridge?`<p>${esc(bridge.securityBasis||bridge.shareBasis||'')}</p>${bridge.warnings?.length>2?list(bridge.warnings.slice(2)):''}${bridge.rows?.length?table('Equity bridge, currency millions',['Item','Amount','Treatment'],bridge.rows.map(x=>[esc(x.label||x.name||x.id),num(x.amount??x.value,2),esc(x.kind+' · '+x.referenceDate)])):''}`:''}${bridgeSensitivityHTML(d,timing)}<p class="micro">Material omitted claims are named here. A source-date proxy is not verified current capital. SBC remains an expense in operating profit; future funding and existing awards are separate questions.</p></details></section>
  ${terminalWarning}<!-- annual-analysis --><div id="research-simulation-root"></div><details class="research-card"><summary>Capital transition and rate sensitivity</summary><p>Current final explicit-year FCFF ${num(r.rows.at(-1).fcff,1)}m; next terminal-year FCFF ${num(r.terminal.fcff,1)}m. FCFF changes ${pct(r.terminal.fcffGrowth)} while terminal revenue grows ${pct(d.terminal.growth)}.</p>${table(`Operating EV sensitivities at forecast origin · ${d.currency} millions`,['Case',`Operating EV · ${d.currency}m`],[['Current annual path',num(r.enterprise,1)],['Three-year capital normalization v1',num(s.normalized,1)],['Normalization difference',num(s.normalizationDelta,1)],...s.rates.filter(x=>x.waccShift!==0).map(x=>[`${x.waccShift>0?'+':'−'}1pp annual and terminal WACC`,num(x.enterprise,1)])])}<p class="micro">Normalization blends only the last three investment amounts toward NOPAT × g / ROIC and leaves revenue, margin, tax and WACC unchanged. An already consistent endpoint is left alone. This is a separately versioned analytical sensitivity, not automatically a better forecast. MU’s revenue-growth endpoint remains a separate disclosure.</p><button class="quiet" data-research-action="normalize">Load capital-normalized sensitivity</button></details>
  ${capitalEvidenceHTML(c,d)}<details class="research-card"><summary>Every annual cash flow and terminal calculation</summary>${table('Calculated annual operating cash flows, currency millions',['Year','Growth','Revenue','EBIT','Tax','NOPAT','Investment','FCFF','PV'],r.rows.map(x=>[esc(x.year),pct(x.growth),num(x.revenue),num(x.ebit),num(x.tax),num(x.nopat),num(x.reinvestment),num(x.fcff),num(x.pv)]))}${table('Next-year terminal calculation, currency millions',['Revenue','NOPAT','Investment','FCFF','Terminal value','PV'],[[num(r.terminal.revenue),num(r.terminal.nopat),num(r.terminal.reinvestment),num(r.terminal.fcff),num(r.terminal.value),num(r.terminalPV)]])}<p class="micro">Annual tax = max(0, EBIT) × tax rate. FCFF = NOPAT − direct investment. Discount factors compound each annual WACC. Terminal value = terminal NOPAT × (1 − g / ROIC) / (WACC − g). Signed operating and common-equity results are retained.</p></details>`;
  if(region==='summary')return markup.split('<!-- annual-analysis -->')[0];
  if(region==='analysis')return markup.split('<!-- annual-analysis -->')[1]||'';
  return markup;
 }catch(error){return region==='analysis'?'<div id="research-simulation-root"></div>':`<div class="error" role="status"><h2>Check the edited annual inputs</h2><p>${esc(error.message)}</p><p>Results are withheld until the inputs are valid. Your draft is retained.</p></div>`;}
}

export function researchEditorHTML(c,d){
 if(!d||!Array.isArray(d.annual)||!d.terminal)return '<p class="error">This saved draft cannot be edited safely. Export it or explicitly load the reviewed case.</p>';
 const fields=[['revenue',`Revenue · ${d.currency}m`,1],['margin','EBIT margin %',100],['taxRate','Operating tax %',100],['reinvestment',`Net investment · ${d.currency}m`,1],['wacc','WACC %',100]];
 const tfields=[['growth','Stable revenue growth %'],['margin','Terminal EBIT margin %'],['taxRate','Terminal tax %'],['roic','Terminal ROIC %'],['wacc','Terminal WACC %']];
 const forecastAnchor=c.anchor.kind==='management_full_year_forecast';
 return `<section class="research-card research-schedule" aria-labelledby="annual-schedule-title"><div class="schedule-heading"><div><span class="eyebrow">EDIT THE BUSINESS PATH</span><h2 id="annual-schedule-title">Annual assumptions</h2></div><span class="auto-status">Updates live</span></div><p>Revenue levels are independent inputs. Changing one year leaves later years unchanged. Net investment is deducted once.</p><div class="annual-anchor"><b>${forecastAnchor?'Management forecast anchor':'Reported / source-derived anchor'} · ${esc(c.anchor.period)}</b><span>Revenue ${num(c.anchor.revenue,1)} ${esc(d.currency)}m${finite(c.anchor.EBIT)&&c.anchor.revenue>0?` · EBIT margin ${pct(c.anchor.EBIT/c.anchor.revenue)}`:''}</span><a href="./data/renewed-research-2026-10-17/evidence-${esc(c.ticker)}.html#facts" target="_blank" rel="noopener">Original evidence ↗</a></div><p id="annual-edit-help" class="micro">${esc(d.currency)} millions; rates in percent. Select a cell to edit its full precision. Display rounding is never saved. Scroll the page to see every year. On narrower screens, each year becomes a labeled group.</p>${table(`Editable annual schedule · ${d.currency} millions; rates in percent`,['Year',...fields.map(x=>x[1])],d.annual.map((r,i)=>[`<span>Year ${r.year}</span><small title="${esc(r.period)}">${esc(compactAnnualPeriod(r))}</small>`,...fields.map(([key,label,scale])=>input(key,r[key],`Year ${r.year} ${label}`,{scale,index:i}))]))}<details class="period-convention"><summary>Period convention and original labels</summary><p>${esc(c.anchor.classification)} First forecast period: ${esc(c.anchor.firstModeledPeriod)}. ${esc(c.anchor.fiscalCalendarCaution||'Calendar-year periods.')}</p>${table('Original source period labels',['Model year','Original period'],d.annual.map(r=>['Year '+r.year,esc(r.period)]))}<p>Investment includes capital spending less D&amp;A and operating working-capital / lease effects where separately modeled.</p></details><details class="terminal-editor"><summary data-terminal-summary>Terminal assumptions · growth ${pct(d.terminal.growth)} · WACC ${pct(d.terminal.wacc)}</summary><div class="research-field-grid">${tfields.map(([key,label])=>`<label>${esc(label)}${input(key,d.terminal[key],label,{group:'terminal',scale:100})}</label>`).join('')}</div></details><p class="micro">Capital-component reconciliations describe the original researched path. After editing investment or margin, check the source economics again; the model does not manufacture a replacement gross-capex budget.</p></section>
 <details class="research-card"><summary>Valuation date and partial-year cash flow</summary><label for="research-timing-mode">Value basis</label><select id="research-timing-mode" data-research-select="timing"><option value="origin" ${d.timing?.mode==='origin'?'selected':''}>Forecast-origin value · no timing assumption</option><option value="as-of-scenario" ${d.timing?.mode==='as-of-scenario'?'selected':''}>Explicit as-of timing scenario</option></select><p>${forecastAnchor?'The revenue base is management’s FY2026 forecast. It is not an observed TTM period. The remaining October 17–December 31 FCFF must be added and the whole future stream discounted over the extra stub interval.':'The annual stream begins at the reported anchor. An October value must remove already-elapsed FCFF before discounting the remaining stream from October.'}</p><div class="research-field-grid"><label>Scenario date<input id="research-asof" type="date" value="${esc(d.timing?.asOf||'2026-10-17')}" data-research-text="asOf" min="2026-10-17"></label><label>${forecastAnchor?'Remaining pre-origin FCFF':'Already-elapsed first-year FCFF'} · millions${input('stubFCFF',d.timing?.stubFCFF,forecastAnchor?'Remaining pre-origin FCFF':'Already elapsed FCFF',{group:'timing'})}</label>${forecastAnchor?`<label>Stub discount rate %${input('stubDiscountRate',d.timing?.stubDiscountRate,'Stub discount rate percent',{group:'timing',scale:100})}</label>`:''}</div><label for="research-stub-reason">Source or explicit timing assumption</label><textarea id="research-stub-reason" rows="3" data-research-text="reason">${esc(d.timing?.reason||'')}</textarea><p class="micro">Blank stays unknown. Entering zero is a substantive assumption and needs an explanation. Calendar proration, if chosen, is an analyst assumption; no realized cash flow is inferred. Dated equity-bridge balances need their own roll-forward.</p></details>
 <details class="research-card"><summary>How Year-by-year differs from Guided</summary><p>Guided generates a path from broad assumptions. Year-by-year exposes individual annual inputs. Both use discounted cash flow, but their assumption paths are separate and are not synchronized. These annual research cases use reviewed company-specific revenue and margin schedules, direct annual investment, company-specific revenue-growth horizons and dated claim adjustments. Those changes can materially change value without any stock-price target.</p><p>MU keeps investing during declining sales. AAOI and NBIS start from explicitly forecast FY2026 anchors. AMZN and GOOG use capital/funding reconciliations. Terminal transitions and uncertainty are shown separately rather than hidden in a smooth curve.</p><p class="micro">Annual Monte Carlo uses the explicit investment-response policy selected in its controls. The complete preset includes explicit company-specific uncertainty assumptions. Fixed zero-offset stresses reproduce the deterministic case; uncertainty and parameter relationships remain analyst judgments. The Guided simulation remains separate.</p></details>`;
}

// This editor changes only the explicit scenario. It never manufactures missing
// claim rows, sources, financing events or reconciliation dates.
function capitalScenarioEditorHTML(c,d){
 const scenario=d.currentCapitalScenario,preset=getCurrentCapitalPreset(c.ticker);
 const load=preset?'<button class="quiet" data-research-action="load-current-capital">Use researched capital scenario</button><p class="micro">Loads dated capital and matching timing only. Annual operating edits and notes stay; Undo last load restores the previous case.</p>':'';
 if(!scenario||typeof scenario!=='object'||Array.isArray(scenario))return `<p class="research-warning">The saved capital scenario needs correction. Its original data is retained for export.</p>${load}`;
 const numberControl=(path,value,label,min=0)=>`<label>${esc(label)}${input(path,value,label,{group:'current-capital',min:min===null?undefined:min})}</label>`;
 const amounts=(rows,path,label)=>Array.isArray(rows)?rows.map((row,index)=>!row||typeof row!=='object'?'<p class="research-warning">Malformed retained claim row; export or reload the capital scenario.</p>':scenario.optionPricing&&['aaoi-note','aaoi-warrant'].includes(row.id)?'':`${numberControl(`${path}.${index}.amount`,row.amount,row.label||row.id, path==='cashAdjustments'?null:0)}<p class="micro">${esc(row.valuationDate||row.date||'')} · ${esc(row.treatment||row.kind||label)}. ${esc(row.rationale||'')}</p>`).join(''):'';
 const pricing=scenario.optionPricing;
 const optionControls=pricing?`<h4>Option-inclusive claim approximation</h4><div class="research-field-grid">${[['volatility','Volatility assumption',100],['creditSpread','Credit spread assumption',100],['riskFreeRate','Risk-free rate proxy',100],['dividendYield','Dividend yield assumption',100],['warrantShares','Existing customer warrant shares · millions',1]].map(([key,label,scale])=>`<label>${esc(label)}${scale===100?' · %':''}${input('optionPricing.'+key,pricing[key],label,{group:'current-capital',scale,min:0})}</label>`).join('')}</div><p class="micro">Note and customer-warrant claims are recalculated with operating value in every valuation and simulation draw. Historical 80% volatility is a selected assumption, not current observed volatility. Do not add conversion shares, exercise shares or proceeds again.</p><details><summary>Contract terms held fixed</summary>${rationaleHTML(Object.fromEntries(Object.entries(pricing).filter(([key])=>!['volatility','creditSpread','riskFreeRate','dividendYield','warrantShares'].includes(key))))}</details>`:'';
 const award=scenario.existingAwardSensitivity;
 const awardControls=award?`<label>Existing employee-award treatment<select data-capital-award-method>${[['none','No quantified award adjustment'],['gross-shares','Gross existing-award shares'],['claim','Existing-award value claim']].map(([key,label])=>`<option value="${key}" ${award.method===key?'selected':''}>${label}</option>`).join('')}</select></label><div data-capital-award-panel="gross-shares" ${award.method==='gross-shares'?'':'hidden'}>${numberControl('existingAwardSensitivity.shares',award.shares,'Existing award shares · millions')}</div><div data-capital-award-panel="claim" ${award.method==='claim'?'':'hidden'}>${numberControl('existingAwardSensitivity.claim',award.claim,'Existing award claim · millions')}</div><p class="micro">${esc(award.rationale)} Shares and claim value are mutually exclusive. Selecting another treatment resets the inactive adjustment to zero; Undo edit restores it.</p>`:'';
 const events=Array.isArray(scenario.events)?scenario.events.map((event,index)=>!event||typeof event!=='object'?'<p class="research-warning">Malformed retained event; export or reload the capital scenario.</p>':`<section><h4>${esc(event.label||event.id)} · ${esc(event.date)}</h4><p class="micro">Completed ${esc(event.kind)}. ${esc(event.rationale)}</p><div class="research-field-grid">${numberControl(`events.${index}.sharesAdded`,event.sharesAdded,'Completed event shares · millions')}${event.kind==='equity-issuance'?numberControl(`events.${index}.issuePrice`,event.issuePrice,'Completed issue price')+numberControl(`events.${index}.fees`,event.fees,'Completed issue fees · millions'):event.kind==='debt-funding'?numberControl(`events.${index}.cashReceived`,event.cashReceived,'Completed debt cash received · millions'):''}${amounts(event.claimsAdded,`events.${index}.claimsAdded`,'New existing claim')}</div></section>`).join(''):'';
 return `<details class="research-card" open><summary>Current capital scenario · editable assumptions</summary><p class="micro">As of ${esc(scenario.asOf)} · ${esc(scenario.currency)} and shares in millions.</p><div class="research-field-grid">${numberControl('baseline.commonShares',scenario.baseline?.commonShares,'Reference common shares · millions')}${numberControl('baseline.cash',scenario.baseline?.cash,'Reference cash · millions')}${numberControl('operatingCashReserve',scenario.operatingCashReserve,'Operating cash reserve · millions')}</div><h4>Existing claims and nonoperating assets</h4><div class="research-field-grid">${amounts(scenario.baseline?.claims,'baseline.claims','Existing claim')}${amounts(scenario.nonoperatingAssets,'nonoperatingAssets','Nonoperating asset')}</div>${scenario.cashAdjustments?.length?`<h4>Cash roll-forward assumptions</h4><div class="research-field-grid">${amounts(scenario.cashAdjustments,'cashAdjustments','Cash adjustment')}</div>`:''}${events}${optionControls}<h4>Existing employee awards</h4>${awardControls}<p class="micro">Future cash use is already deducted through negative FCFF. Future fundraising shares and a second funding-deficit deduction are not added automatically. These controls describe existing capital and completed financing; changes are analyst assumptions.</p><details><summary>Capital scenario sources and limitations</summary><p>${esc(scenario.rationale)}</p><p class="micro">Cash reference ${esc(scenario.baseline?.cashDate)} · share reference ${esc(scenario.baseline?.shareDate)}. Dates and completed-event matching do not move automatically when timing changes.</p><p class="micro">Reference-case rationale below describes the researched starting assumptions. Edited controls and the current result above take precedence.</p>${d.currentCapitalProvenance?.reportPath?`<p>${link(d.currentCapitalProvenance.reportPath,'Read the dated capital scenario review')}</p>`:''}${rationaleHTML(d.currentCapitalProvenance||{})}${(d.currentCapitalProvenance?.sourceUrls||[]).map(url=>link(url,'Original source')).join(' · ')}${list(scenario.unresolved||[])}${(Array.isArray(scenario.sources)?scenario.sources:[]).filter(source=>source&&(typeof source==='string'||typeof source.url==='string')).map(source=>link(typeof source==='string'?source:source.url,typeof source==='string'?'Capital source':source.label||source.date||'Capital source')).join(' · ')}</details>${load}</details>`;
}
export function researchClaimsEditorHTML(c,d){
 if(Object.prototype.hasOwnProperty.call(d||{},'currentCapitalScenario'))return capitalScenarioEditorHTML(c,d);
 const definition=researchBridgeDefinition(c.ticker);if(!definition)return '';
 const controls=definition.optionDefinitions.map(field=>{
  const value=Object.prototype.hasOwnProperty.call(d.bridgeInputs||{},field.key)?d.bridgeInputs[field.key]:field.default;
  if(field.type==='select')return `<label>${esc(field.label)}<select data-research-claim-select="${esc(field.key)}">${field.values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
  const scale=field.max===1?100:1,label=field.label+(scale===100?' · %':'');
  return `<label>${esc(label)}${input(field.key,value,label,{group:'bridge',scale,min:field.min==null?undefined:field.min*scale,max:field.max==null?undefined:field.max*scale})}${value===null?'<small>Required amount is unknown; blank does not mean zero.</small>':''}</label>`;
 }).join('');
 const currentLoad=getCurrentCapitalPreset(c.ticker)?'<button class="quiet" data-research-action="load-current-capital">Use researched capital scenario</button><p class="micro">Loads dated capital and matching timing only; operating edits stay. Undo last load restores the previous case.</p>':'';
 return `<details class="research-card"><summary>Equity-bridge assumptions and sensitivities</summary><p>Capital reference ${esc(definition.referenceDate)}, shares ${esc(definition.shareDate)}. These are disclosed source-date allocation assumptions. An additional claim allowance of zero does not verify that unresolved claims are absent.</p><div class="research-field-grid">${controls}</div><p>${link(definition.sourceUrl,'Original capital-reference source')} · ${link(`./data/renewed-research-2026-10-17/evidence-${c.ticker}.html#claims`,'Complete claims register')}</p>${c.ticker==='LITE'?`<p>Fresh June defaults use 6,052.9 of disclosed note fair-value adjustment above principal and approximately 200 of capped-call value. Saved numbers and explicit blanks are retained. ${d.bridgeReviewVersion==='legacy-preserved-v1'?'This older saved draft keeps its prior unknown/entered note adjustment and prior call-credit assumption until you choose to load the reviewed values. ':''}${link(definition.reviewPath,'Read the dated bridge review')}</p><button class="quiet" data-research-action="load-bridge">Load reviewed June bridge values</button><p class="micro">This changes only the two LITE claim values above. Undo last load restores the full previous draft. The principal-only stress and any other edits stay explicit assumptions.</p>`:''}<p class="micro">Edits update only this annual research draft. Clearing a claim amount leaves it unknown. Gross-share stresses are not option valuations. AAOI and NBIS require date-consistent funding/ownership bridges before common-equity output.</p>${currentLoad}</details>`;
}

